def entry(slug, name, issue_category, owasp, cwe_ids, match_keywords, explanation, business_impact, remediation_steps, base_priority, references=()):
    return {
        "slug": slug, "name": name, "issue_category": issue_category, "owasp_category": OWASP[owasp], "cwe_ids": list(cwe_ids),
        "match_keywords": list(match_keywords), "explanation": explanation, "business_impact": business_impact,
        "remediation_steps": list(remediation_steps), "base_priority": base_priority, "references": list(references),
    }


